<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Activity, RefreshCw, Cpu } from '@lucide/vue'
import { api } from '../api'
const data=ref<any>(null);const error=ref('')
async function load(){try{data.value=await api('/admin/observability')}catch(e:any){error.value=e.message}}
const fmt=(v:string)=>new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})
onMounted(load)
</script>
<template><section class="page-heading"><div><div class="eyebrow">Operations</div><h1>看见每次模型调用，<br>也看见失败。</h1><p>任务状态、调用目的、耗时与错误集中在一个低噪声视图。</p></div><button class="button" @click="load"><RefreshCw :size="17"/>刷新</button></section><div v-if="error" class="notice error">{{error}}</div><div v-else-if="!data" class="loading">LOADING OBSERVABILITY…</div><div v-else><section class="grid four" style="margin-bottom:16px"><article class="card stat-card"><Activity :size="20"/><div><span class="eyebrow">排队任务</span><strong>{{data.summary.jobs_queued}}</strong></div></article><article class="card stat-card"><Activity :size="20"/><div><span class="eyebrow">失败任务</span><strong>{{data.summary.jobs_failed}}</strong></div></article><article class="card stat-card"><Cpu :size="20"/><div><span class="eyebrow">模型调用</span><strong>{{data.summary.ai_calls}}</strong></div></article><article class="card stat-card dark"><Cpu :size="20"/><div><span class="eyebrow" style="color:#9fc9cb">模型失败</span><strong>{{data.summary.ai_failures}}</strong></div></article></section><section class="grid two"><article class="card paper"><header class="card-header"><div><div class="kicker">Job queue</div><h2>任务</h2></div></header><div class="list-stack"><div v-for="job in data.jobs.slice(0,12)" :key="job.id" class="list-row" style="grid-template-columns:1fr .7fr auto"><div><h3>{{job.kind}}</h3><p>#{{job.id}} · meeting {{job.meeting_id}}</p></div><span :class="['status',job.status==='failed'?'failed':job.status==='queued'?'warning':'']">{{job.status}}</span><span class="mono" style="font-size:10px">{{fmt(job.created_at)}}</span></div></div></article><article class="card"><header class="card-header"><div><div class="kicker">AI calls</div><h2>模型调用</h2></div></header><div v-if="!data.ai_calls.length" class="empty">尚无真实模型调用。无 API Key 时系统使用确定性降级。</div><div v-else class="list-stack"><div v-for="call in data.ai_calls.slice(0,12)" :key="call.id" class="list-row" style="grid-template-columns:1fr .7fr auto"><div><h3>{{call.purpose}}</h3><p>{{call.model}} · {{call.duration_ms}} ms</p></div><span :class="['status',call.success?'':'failed']">{{call.success?'success':'failed'}}</span><span class="mono" style="font-size:10px">{{call.prompt_tokens+call.completion_tokens}} tok</span></div></div></article></section><article class="card dark" style="margin-top:16px"><div class="bars"><i style="--h:35%"/><i style="--h:58%"/><i style="--h:46%"/><i style="--h:78%"/><i style="--h:62%"/><i style="--h:88%"/><i style="--h:71%"/><i style="--h:52%"/><i style="--h:67%"/><i style="--h:42%"/><i style="--h:73%"/><i style="--h:56%"/></div><p class="mono" style="margin:16px 0 0">示意：任务吞吐；生产指标接口可继续接入 Prometheus。</p></article></div></template>
